// Symptom: Operations and the Timeline lay out side by side in a row.
// Expected: they stack vertically (single column).
await page.goto('/ops/operations');

const operations = page.getByRole('region', { name: 'Operations' });
const timeline = page.getByRole('region', { name: 'Timeline' });

await expect(operations).toBeVisible();
await expect(timeline).toBeVisible();

// The shared container must not lay its children out in a row.
const layout = operations.locator('xpath=..');
await expect(layout).not.toHaveCSS('flex-direction', 'row');
await expect(layout).not.toHaveCSS('grid-auto-flow', 'column');
```

